# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KÜLTÜR YOLCULUĞU: TÜRK DÜNYASI HİKÂYESİ VE GEZİ YAZISI UNSURLARI</text>\n  <rect x="20" y="44" width="210" height="194" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Ortak Kültür ve Dil Mirası</text>\n  <rect x="34" y="78" width="182" height="30" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="97" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Orhun\'dan Çağdaş Türk Dünyasına</text>\n  <text x="32" y="126" font-size="10" fill="#334155">• <tspan font-weight="bold">Orhun Abideleri:</tspan> Bilge Kağan,</text>\n  <text x="40" y="141" font-size="10" fill="#334155">Kül Tigin ve Tonyukuk yazıtları.</text>\n  <text x="32" y="163" font-size="10" fill="#334155">• <tspan font-weight="bold">Dîvânu Lugâti\'t-Türk:</tspan> Türk</text>\n  <text x="40" y="178" font-size="10" fill="#334155">boylarının dil ve kültür hazinesi.</text>\n  <text x="32" y="200" font-size="10" fill="#334155">• <tspan font-weight="bold">Temel Değerler:</tspan> Ana dili bilinci,</text>\n  <text x="40" y="215" font-size="10" fill="#334155">vatan sevgisi, töre ve vefa.</text>\n\n  <rect x="245" y="44" width="210" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">2. Türk Dünyası Hikâyesi</text>\n  <rect x="259" y="78" width="182" height="30" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="350" y="97" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">Hafıza, Kimlik ve İnsanî Öz</text>\n  <text x="257" y="126" font-size="10" fill="#334155">• <tspan font-weight="bold">Cengiz Aytmatov:</tspan> Halk efsane</text>\n  <text x="265" y="141" font-size="10" fill="#334155">ve destanlarını modern hikâye</text>\n  <text x="265" y="156" font-size="10" fill="#334155">ve romanla birleştirmiştir.</text>\n  <text x="257" y="178" font-size="10" fill="#334155">• <tspan font-weight="bold">Temel Çatışma:</tspan> Köklerine bağlılık</text>\n  <text x="265" y="193" font-size="10" fill="#334155">ile kimlik yabancılaşması</text>\n  <text x="265" y="208" font-size="10" fill="#334155">(mankurtlaşma) arasındaki mücadele.</text>\n\n  <rect x="470" y="44" width="210" height="194" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">3. Gezi Yazısı (Seyahatname)</text>\n  <rect x="484" y="78" width="182" height="30" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="575" y="97" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Gözlem + Kültür Aktarımı</text>\n  <text x="482" y="126" font-size="10" fill="#334155">• Gezilip görülen coğrafyaların</text>\n  <text x="490" y="141" font-size="10" fill="#334155">tarihî, mimari ve beşerî</text>\n  <text x="490" y="156" font-size="10" fill="#334155">dokusu gözlemle betimlenir.</text>\n  <text x="482" y="178" font-size="10" fill="#334155">• <tspan font-weight="bold">Klasik:</tspan> Mir\'âtü\'l-Memâlik,</text>\n  <text x="490" y="193" font-size="10" fill="#334155">Evliya Çelebi Seyahatnâme\'si.</text>\n  <text x="482" y="212" font-size="10" fill="#334155">• <tspan font-weight="bold">Modern:</tspan> Anadolu Notları,</text>\n  <text x="490" y="226" font-size="10" fill="#334155">Türkistan Türkistan, Tuna\'dan...</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">CÜMLENİN TEMEL ÖGELERİ: YÜKLEM VE ÖZNE TÜRLERİ</text>\n  <rect x="20" y="44" width="320" height="194" rx="10" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#5b21b6">1. Yüklem (Yargıyı Bildiren Temel Öge)</text>\n  <rect x="34" y="78" width="292" height="32" rx="6" fill="#ffffff" stroke="#8b5cf6" stroke-width="1.5"/>\n  <text x="180" y="98" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#6d28d9">Altın Kural: Tamlamalar ve Deyimler Bölünmez!</text>\n  <text x="34" y="128" font-size="10" fill="#334155">• Çekimli fiil veya ek fiil (-idi, -imiş, -ise, -dir)</text>\n  <text x="42" y="143" font-size="10" fill="#334155">almış isim soylu sözcük/söz öbeğidir.</text>\n  <text x="34" y="166" font-size="10" font-weight="bold" fill="#5b21b6">• Örnek (Sıfat Tamlaması Yüklem):</text>\n  <text x="34" y="182" font-size="10" fill="#334155">"Semerkant, <tspan font-weight="bold" fill="#dc2626">asırlık kubbelerin parladığı kadim</tspan></text>\n  <text x="34" y="197" font-size="10" fill="#334155"><tspan font-weight="bold" fill="#dc2626">bir Türk şehridir</tspan>." (Tamamı yüklemdir!)</text>\n  <text x="34" y="218" font-size="10" fill="#334155">• Önce yüklem, hemen ardından özne bulunur.</text>\n\n  <rect x="360" y="44" width="320" height="194" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">2. Özne (Yapan Kim? / Olan Ne?)</text>\n  <rect x="374" y="78" width="292" height="32" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="520" y="98" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Gerçek (Açık / Gizli) Özne  ve  Sözde Özne</text>\n  <text x="374" y="128" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Gerçek Özne:</tspan> İşi bizzat yapan ögedir.</text>\n  <text x="382" y="143" font-size="9.5" fill="#475569">Örn: "<tspan font-weight="bold">Kaşgarlı Mahmud</tspan> Dîvân\'ı Bağdat\'ta sundu."</text>\n  <text x="374" y="165" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Gizli Özne:</tspan> Şahıs ekinden anlaşılır; öge</text>\n  <text x="382" y="180" font-size="9.5" fill="#475569">sayısına ve dizilişine dahil edilmez.</text>\n  <text x="374" y="202" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Sözde Özne:</tspan> Edilgen (-l/-n) fiilde işten etkilenen.</text>\n  <text x="382" y="217" font-size="9.5" fill="#475569">Örn: "<tspan font-weight="bold">Orhun Yazıtları</tspan> 1893\'te okundu."</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">YARDIMCI ÖGELER TABLOSU, VURGU VE CÜMLE DIŞI UNSURLAR</text>\n  <rect x="20" y="44" width="415" height="194" rx="10" fill="#ffffff" stroke="#2563eb" stroke-width="2"/>\n  <rect x="20" y="44" width="415" height="26" rx="8" fill="#2563eb"/>\n  <text x="95" y="61" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#ffffff">Yardımcı Öge</text>\n  <text x="260" y="61" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#ffffff">Yükleme Sorulan Sorular</text>\n  <text x="392" y="61" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#ffffff">Hal Eki</text>\n\n  <text x="30" y="90" font-size="10.5" font-weight="bold" fill="#1e40af">Belirtili Nesne</text>\n  <text x="165" y="90" font-size="10" fill="#334155">Neyi? Kimi? Nereyi? Hangi ...-ı?</text>\n  <text x="392" y="90" text-anchor="middle" font-size="10" font-weight="bold" fill="#dc2626">-ı, -i, -u, -ü</text>\n  <line x1="28" y1="100" x2="425" y2="100" stroke="#cbd5e1" stroke-width="1"/>\n\n  <text x="30" y="120" font-size="10.5" font-weight="bold" fill="#1e40af">Belirtisiz Nesne</text>\n  <text x="165" y="120" font-size="10" fill="#334155">Ne? (Özne bulunduktan sonra)</text>\n  <text x="392" y="120" text-anchor="middle" font-size="10" fill="#334155">Yalın (Eksiz)</text>\n  <line x1="28" y1="130" x2="425" y2="130" stroke="#cbd5e1" stroke-width="1"/>\n\n  <text x="30" y="152" font-size="10.5" font-weight="bold" fill="#15803d">Yer Tamlayıcısı</text>\n  <text x="30" y="165" font-size="9" fill="#15803d">(Dolaylı Tümleç)</text>\n  <text x="165" y="152" font-size="10" fill="#334155">Kime, kimde, kimden? Neye,</text>\n  <text x="165" y="165" font-size="10" fill="#334155">nerede, nereden?</text>\n  <text x="392" y="158" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">-e / -de / -den</text>\n  <line x1="28" y1="176" x2="425" y2="176" stroke="#cbd5e1" stroke-width="1"/>\n\n  <text x="30" y="198" font-size="10.5" font-weight="bold" fill="#b45309">Zarf Tümleci</text>\n  <text x="165" y="198" font-size="10" fill="#334155">Nasıl, ne zaman, ne kadar, niçin,</text>\n  <text x="165" y="212" font-size="10" fill="#334155">nere (eksiz), neyle, kiminle?</text>\n  <text x="392" y="205" text-anchor="middle" font-size="10" fill="#334155">Durum/Zaman</text>\n\n  <rect x="448" y="44" width="232" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="564" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Vurgu ve Örnek Çözümleme</text>\n  <rect x="460" y="76" width="208" height="68" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.2"/>\n  <text x="468" y="93" font-size="9.5" font-weight="bold" fill="#78350f">Örnek Cümle:</text>\n  <text x="468" y="108" font-size="9.5" fill="#1e293b">"Seyyah (Ö), dün (ZT) Buhara\'da (YT)</text>\n  <text x="468" y="122" font-size="9.5" fill="#1e293b"><tspan font-weight="bold" fill="#dc2626">tarihî medreseleri (BN)</tspan> inceledi (Y)."</text>\n  <text x="468" y="137" font-size="9" font-weight="bold" fill="#dc2626">→ Vurgu: Belirtili Nesne üzerindedir.</text>\n  <text x="460" y="162" font-size="9.5" fill="#334155">• <tspan font-weight="bold" fill="#92400e">Fiil Cümlesinde Vurgu:</tspan> Yüklemden</text>\n  <text x="468" y="176" font-size="9.5" fill="#334155">hemen önceki öge vurgulanır.</text>\n  <text x="460" y="194" font-size="9.5" fill="#334155">• <tspan font-weight="bold" fill="#92400e">İsim Cümlesinde Vurgu:</tspan> Yüklemdedir.</text>\n  <text x="460" y="212" font-size="9.5" fill="#334155">• <tspan font-weight="bold" fill="#92400e">CDU:</tspan> Bağlaç, ünlem, hitap, ara cümle.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
